import {
    CircleCheck,
    CircleDashed,
    CircleExclamation,
    CirclePause,
    CirclePlay,
    CircleQuestion,
    CircleStop,
    CircleXmark,
    SealCheck,
} from '@gravity-ui/icons';
import {type IconData} from '@gravity-ui/uikit';

import {GoalStatus, IssueStatus, MetaEntityStatus} from './types';

export function getSvgForStatusType(
    statusType?: IssueStatus | MetaEntityStatus | GoalStatus,
): IconData {
    switch (statusType) {
        case 'new':
        case 'draft':
        case 'draft2':
            return CircleDashed;
        case 'done':
        case 'launched':
        case 'achieved':
        case 'partially_achieved':
            return CircleCheck;
        case 'cancelled':
        case 'not_achieved':
            return CircleXmark;
        case 'inProgress':
        case 'in_progress':
        case 'according_to_plan':
            return CirclePlay;
        case 'paused':
        case 'postponed':
            return CirclePause;
        case 'at_risk':
            return CircleExclamation;
        case 'exceeded':
            return SealCheck;
        case 'blocked':
            return CircleStop;
        default:
            return CircleQuestion;
    }
}
